        angle = math.radians(float(berth.heading_deg))
        along_east, along_north = math.sin(angle), math.cos(angle)
        right_east, right_north = math.cos(angle), -math.sin(angle)
        side_offset = float(berth.width_m) if berth.water_side == 'right' else 0.0
