            east_m = along_east * distance + right_east * side_offset
            north_m = along_north * distance + right_north * side_offset
            bollard.latitude = latitude + math.degrees(north_m / EARTH_RADIUS_M)
            bollard.longitude = float(berth.longitude) + math.degrees(east_m / longitude_scale)
            bollard.save(update_fields=['latitude', 'longitude'])


